	/**
	 * Hook the gettext filter.
	 */
	public static function init() {
		add_filter( 'gettext', array( __CLASS__, 'translate' ), 10, 3 );
	}

	/**
	 * Translate strings of this plugin to Persian.
	 *
	 * @param string $translation Translated text.
	 * @param string $text        Source text.
	 * @param string $domain      Text domain.
	 * @return string
	 */
	public static function translate( $translation, $text, $domain ) {
		if ( 'hooshyar-commerce-kit' === $domain && isset( self::$map[ $text ] ) ) {
			return self::$map[ $text ];
		}
		return $translation;
	}
}
